package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;
import java.util.zip.*;
import org.jlinalg.sequence.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

/** Original FASTA/FAI/PFM controls for independent metadata and motif-output structural auditing. */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class SignacScanAuditTest {
    @TempDir static Path root;
    private Map<String,Object> cases,original;
    private final AtomicInteger files=new AtomicInteger();
    private record Input(List<SignacPfmIO.Model> models,List<SignacFragments.Region> peaks,SignacReferenceStats.Result reference,SignacMotifEnrichment.Matrix matrix,List<SignacMotifScanAudit.Hit> hits,String profile) { }
    @BeforeAll void fixture()throws Exception{byte[] raw;try(var in=getClass().getResourceAsStream("/org/jlinalg/sequence/signac-scan/original-controls.zip")){assertNotNull(in);raw=in.readAllBytes();}assertEquals("c09d5afa6e73d376522bd990c6b7260e7eef78386990712706e9d5ddc7c5005b",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw)));try(var zip=new ZipInputStream(new ByteArrayInputStream(raw))){java.util.zip.ZipEntry e;while((e=zip.getNextEntry())!=null){Path path=root.resolve(e.getName()).normalize();assertTrue(path.startsWith(root));Files.createDirectories(path.getParent());Files.write(path,zip.readAllBytes());}}cases=object(SimpleJson.parse(Files.readString(root.resolve("cases.json"),StandardCharsets.UTF_8)));original=object(SimpleJson.parse(Files.readString(root.resolve("original.json"),StandardCharsets.UTF_8)));}
    @TestFactory Stream<DynamicTest> fullOriginalMetadata(){List<DynamicTest> tests=new ArrayList<>();for(var record:successes())tests.add(DynamicTest.dynamicTest(text(record,"profile")+"/"+text(record,"id"),()->{
        Input in=input(record);var expected=array(result(record).get("metadata"));assertEquals(in.reference.rows().size(),expected.size());for(int i=0;i<expected.size();i++){var row=object(expected.get(i));var got=in.reference.rows().get(i);assertEquals(text(row,"_row"),got.peak());assertEquals(((Number)row.get("sequence.length")).intValue(),got.sequenceLength());if(got.chromosomePresent()){assertEquals(((Number)row.get("GC.percent")).doubleValue(),got.gcPercent(),2e-12);for(int j=0;j<16;j++)assertEquals(((Number)row.get(SignacReferenceStats.DINUCLEOTIDES.get(j))).longValue(),got.dinucleotides()[j]);}else{assertEquals("NA",row.get("GC.percent"));assertTrue(Double.isNaN(got.gcPercent()));for(String key:SignacReferenceStats.DINUCLEOTIDES)assertEquals("NA",row.get(key));}}
    }));return tests.stream();}
    @TestFactory Stream<DynamicTest> fullOriginalPositionMatrixBindings(){return successes().stream().map(record->DynamicTest.dynamicTest(text(record,"profile")+"/"+text(record,"id"),()->{Input in=input(record);var got=audit(in,in.matrix,in.hits,in.models);assertEquals(in.hits.size(),got.hits());assertEquals(Arrays.stream(in.matrix.values()).filter(v->v==1).count(),got.matrixPresenceEntries());assertEquals(Boolean.TRUE,record.get("qualified_getSeq_restored"));}));}
    @TestFactory Stream<DynamicTest> typedPFMModels(){return object(cases.get("datasets")).entrySet().stream().map(entry->DynamicTest.dynamicTest(entry.getKey(),()->{var data=object(entry.getValue());var expected=list(data.get("pfms"));var got=models(data);assertEquals(expected.size(),got.size());for(int i=0;i<got.size();i++){var want=object(expected.get(i));assertEquals(text(want,"id"),got.get(i).id());assertEquals(text(want,"name"),got.get(i).name());assertArrayEquals(array(want.get("background")).stream().mapToDouble(v->((Number)v).doubleValue()).toArray(),got.get(i).background());var rows=list(want.get("rows"));assertEquals(rows.size(),got.get(i).positions().length);for(int j=0;j<rows.size();j++)assertArrayEquals(list(rows.get(j)).stream().mapToDouble(v->((Number)v).doubleValue()).toArray(),got.get(i).positions()[j]);}}));}
    @TestFactory Stream<DynamicTest> alteredStructuralEvidence(){List<DynamicTest> tests=new ArrayList<>();for(String name:List.of("unknown-motif","wrong-width","outside-peaks","nonbinary","missing-presence","missing-motif-hits","model-order","missing-source-placeholder"))tests.add(DynamicTest.dynamicTest(name,()->{
        Input in=baseline(name.equals("missing-source-placeholder")?"missing-chromosome":"matched");var matrix=in.matrix;List<SignacMotifScanAudit.Hit> hits=new ArrayList<>(in.hits);List<SignacPfmIO.Model> models=new ArrayList<>(in.models);var first=hits.get(0);
        switch(name){case "unknown-motif"->hits.set(0,new SignacMotifScanAudit.Hit("unknown",first.chromosome(),first.start(),first.end(),first.strand(),first.score()));case "wrong-width"->hits.set(0,new SignacMotifScanAudit.Hit(first.motif(),first.chromosome(),first.start(),first.end()+1,first.strand(),first.score()));case "outside-peaks"->hits.set(0,new SignacMotifScanAudit.Hit(first.motif(),first.chromosome(),1,first.end()-first.start()+1,first.strand(),first.score()));case "missing-motif-hits"->hits.removeIf(v->v.motif().equals(first.motif()));case "model-order"->Collections.swap(models,0,1);default->{double[] values=matrix.values();if(name.equals("missing-source-placeholder")){int last=matrix.motifs().size()-1;int[] pointers=matrix.pointers(),rows=matrix.rows();boolean found=false;for(int i=pointers[last];i<pointers[last+1];i++)if(rows[i]==matrix.peaks().size()-1){values[i]=0;found=true;}assertTrue(found);}else values[0]=name.equals("nonbinary")?2:0;matrix=new SignacMotifEnrichment.Matrix(matrix.peaks(),matrix.motifs(),matrix.names(),matrix.pointers(),matrix.rows(),values);}}
        var changed=matrix;assertThrows(IOException.class,()->audit(in,changed,hits,models));
    }));return tests.stream();}
    @Test void wrappedCRLFFastaRetainsOriginalStatistics()throws Exception{var record=successes().stream().filter(v->v.get("profile").equals("1.17.1-package")&&v.get("id").equals("matched")).findFirst().orElseThrow();Input in=input(record);var data=dataset(record);Path file=folder().resolve("wrapped.fa");StringBuilder text=new StringBuilder();for(var e:object(data.get("sequences")).entrySet()){text.append('>').append(e.getKey()).append(" description\r\n");String sequence=(String)e.getValue();for(int i=0;i<sequence.length();i+=60)text.append(sequence,i,Math.min(sequence.length(),i+60)).append("\r\n");}Files.writeString(file,text,StandardCharsets.UTF_8);var got=SignacReferenceStats.calculate(file,null,in.peaks,SignacReferenceStats.Limits.defaults(),()->false);for(int i=0;i<got.rows().size();i++){assertEquals(in.reference.rows().get(i).gcPercent(),got.rows().get(i).gcPercent());assertArrayEquals(in.reference.rows().get(i).dinucleotides(),got.rows().get(i).dinucleotides());}}
    @Test void malformedFastaIsRejected()throws Exception{for(String text:List.of("ACGT\n",">x\nAC GT\n",">x\nACGU\n",">x\nACGT\n>x\nACGT\n",">x\n>x2\nA\n",">x\n",">x\nAC\rGT\n",">x\nACGT\r")){Path file=folder().resolve("bad.fa");Files.writeString(file,text);assertThrows(IOException.class,()->SignacReferenceStats.inspect(file,SignacReferenceStats.Limits.defaults(),()->false));}}
    @Test void compressedReferenceIsExplicitlyRejected()throws Exception{Path file=folder().resolve("reference.fa.gz");try(var out=new GZIPOutputStream(Files.newOutputStream(file))){out.write(">x\nACGT\n".getBytes(StandardCharsets.UTF_8));}var error=assertThrows(IOException.class,()->SignacReferenceStats.inspect(file,SignacReferenceStats.Limits.defaults(),()->false));assertTrue(error.getMessage().contains("gzi"));}
    @Test void staleCapturedFaiIsRejected()throws Exception{Input in=baseline("matched");Path file=root.resolve("control-072/reference.fa"),index=folder().resolve("stale.fai");String old=Files.readString(root.resolve("control-072/reference.fa.fai"));Files.writeString(index,old.replaceFirst("24000","23999"));assertThrows(IOException.class,()->SignacReferenceStats.calculate(file,index,in.peaks,SignacReferenceStats.Limits.defaults(),()->false));}
    @Test void outOfRangePeakFails()throws Exception{var peaks=List.of(new SignacFragments.Region("chr1",23900,24100));assertThrows(IOException.class,()->SignacReferenceStats.calculate(root.resolve("control-072/reference.fa"),null,peaks,SignacReferenceStats.Limits.defaults(),()->false));}
    @Test void absentChromosomeRetainsWidthAndMissingClass()throws Exception{var result=SignacReferenceStats.calculate(root.resolve("control-072/reference.fa"),null,List.of(new SignacFragments.Region("absent",1,10)),SignacReferenceStats.Limits.defaults(),()->false);assertFalse(result.rows().get(0).chromosomePresent());assertEquals(10,result.rows().get(0).sequenceLength());assertTrue(Double.isNaN(result.rows().get(0).gcPercent()));assertEquals(0,result.queriedBases());assertTrue(result.warnings().stream().anyMatch(v->v.startsWith("MISSING_REFERENCE_CHROMOSOMES")));}
    @Test void referenceAndModelArraysAreImmutable()throws Exception{Input in=baseline("matched");long first=in.reference.rows().get(0).dinucleotides()[0];in.reference.rows().get(0).dinucleotides()[0]=999;assertEquals(first,in.reference.rows().get(0).dinucleotides()[0]);assertThrows(UnsupportedOperationException.class,()->in.reference.reference().lengths().put("changed",1L));double value=in.models.get(0).positions()[0][0];in.models.get(0).positions()[0][0]=999;in.models.get(0).background()[0]=999;assertEquals(value,in.models.get(0).positions()[0][0]);assertEquals(.25,in.models.get(0).background()[0]);}
    @Test void referenceAndQueryCapacitiesFail()throws Exception{Input in=baseline("matched");var limits=SignacReferenceStats.Limits.defaults();assertThrows(IOException.class,()->SignacReferenceStats.calculate(root.resolve("control-072/reference.fa"),null,in.peaks,new SignacReferenceStats.Limits(1,limits.residues(),limits.sequences(),limits.lineBases(),limits.peakWidth(),limits.peaks(),limits.queriedBases()),()->false));assertThrows(IOException.class,()->SignacReferenceStats.calculate(root.resolve("control-072/reference.fa"),null,in.peaks,new SignacReferenceStats.Limits(limits.bytes(),limits.residues(),limits.sequences(),limits.lineBases(),limits.peakWidth(),limits.peaks(),1),()->false));}
    @Test void cancellationStopsActualReferenceWork()throws Exception{Input in=baseline("matched");AtomicInteger checks=new AtomicInteger();assertThrows(CancellationException.class,()->SignacReferenceStats.calculate(root.resolve("control-072/reference.fa"),null,in.peaks,SignacReferenceStats.Limits.defaults(),()->checks.incrementAndGet()>3));}
    @Test void invalidTypedPfmsAreRejected()throws Exception{String row="M\tTF\t1\t40\t1\t1\t1\t0.25\t0.25\t0.25\t0.25\n";for(String text:List.of("wrong\n"+row,SignacPfmIO.HEADER+"\n"+row.replace("\t1\t40","\t2\t40"),SignacPfmIO.HEADER+"\n"+row.replace("40","NaN"),SignacPfmIO.HEADER+"\n"+row.replace("0.25","0.20"),SignacPfmIO.HEADER+"\n"+row+row)){Path file=folder().resolve("bad.tsv");Files.writeString(file,text);assertThrows(IOException.class,()->SignacPfmIO.read(file,SignacPfmIO.Limits.defaults(),()->false));}}
    @Test void typedPfmUnicodeLabelsAreExact()throws Exception{var data=object(object(cases.get("datasets")).get("base"));assertEquals("ACGT α",models(data).get(0).name());Path file=folder().resolve("bad-utf8.tsv");Files.write(file,new byte[]{(byte)0xff,10});assertThrows(IOException.class,()->SignacPfmIO.read(file,SignacPfmIO.Limits.defaults(),()->false));}
    @Test void fractionalPfmCountsAreNotNormalized()throws Exception{var data=object(object(cases.get("datasets")).get("fractional-pfm"));assertArrayEquals(new double[]{40.5,1.25,1.5,1},models(data).get(0).positions()[0]);}
    @Test void typedPfmCapacityIsExplicit()throws Exception{var data=object(object(cases.get("datasets")).get("base"));Path file=writeModels(data);assertThrows(IOException.class,()->SignacPfmIO.read(file,new SignacPfmIO.Limits(1000000,1,512,2000000,16384),()->false));assertThrows(CancellationException.class,()->SignacPfmIO.read(file,SignacPfmIO.Limits.defaults(),()->true));}
    @Test void structuralAuditIsBoundedAndDoesNotCertifyScores()throws Exception{Input in=baseline("matched");assertThrows(IllegalArgumentException.class,()->SignacMotifScanAudit.audit(in.models,in.peaks,in.reference,in.matrix,in.hits,in.profile,1,()->false));var result=audit(in,in.matrix,in.hits,in.models);assertTrue(result.warnings().stream().anyMatch(v->v.startsWith("UPSTREAM_MOODS_SCORING")));}
    @Test void missingChromosomePlaceholderIsNotAnObservedHit()throws Exception{Input in=baseline("missing-chromosome");var result=audit(in,in.matrix,in.hits,in.models);assertEquals(1,result.sourcePlaceholderEntries());assertEquals(1,result.missingChromosomeRows());assertTrue(result.warnings().stream().anyMatch(v->v.startsWith("SOURCE_MISSING_CHROMOSOME_PLACEHOLDER")));assertTrue(in.hits.stream().noneMatch(v->v.chromosome().equals("chrAbsent")));}
    private SignacMotifScanAudit.Result audit(Input in,SignacMotifEnrichment.Matrix matrix,List<SignacMotifScanAudit.Hit> hits,List<SignacPfmIO.Model> models)throws IOException{return SignacMotifScanAudit.audit(models,in.peaks,in.reference,matrix,hits,in.profile,100000000,()->false);}
    private Input baseline(String name)throws Exception{return input(successes().stream().filter(v->v.get("profile").equals("1.17.1-package")&&v.get("id").equals(name)).findFirst().orElseThrow());}
    private Input input(Map<String,Object> record)throws Exception{var d=dataset(record);var value=result(record);List<SignacFragments.Region> peaks=new ArrayList<>();for(Object raw:list(d.get("peaks"))){var p=object(raw);peaks.add(new SignacFragments.Region(text(p,"chromosome"),integer(p,"start"),integer(p,"end")));}Path file=root.resolve(text(record,"folder")).resolve("reference.fa");var ref=SignacReferenceStats.calculate(file,file.resolveSibling("reference.fa.fai"),peaks,SignacReferenceStats.Limits.defaults(),()->false);List<String> motifIds=strings(value.get("motif_ids"));Map<String,Object> labels=object(value.get("motif_names"));List<String> names=motifIds.stream().map(v->(String)labels.get(v)).toList();int[] pointers=new int[motifIds.size()+1];List<Integer> rows=new ArrayList<>();List<Double> vals=new ArrayList<>();var matrix=list(value.get("motif_matrix"));for(int column=0;column<motifIds.size();column++){for(int row=0;row<peaks.size();row++){Object x=list(matrix.get(row)).get(column);double n=x instanceof Boolean b?b?1:0:((Number)x).doubleValue();if(n!=0){rows.add(row);vals.add(n);}}pointers[column+1]=vals.size();}var m=new SignacMotifEnrichment.Matrix(peaks.stream().map(SignacFragments.Region::name).toList(),motifIds,names,pointers,rows.stream().mapToInt(Integer::intValue).toArray(),vals.stream().mapToDouble(Double::doubleValue).toArray());List<SignacMotifScanAudit.Hit> hits=new ArrayList<>();for(var entry:object(value.get("positions")).entrySet())for(Object raw:array(entry.getValue())){var hit=object(raw);hits.add(new SignacMotifScanAudit.Hit(entry.getKey(),text(hit,"seqnames"),integer(hit,"start"),integer(hit,"end"),text(hit,"strand"),((Number)hit.get("score")).doubleValue()));}return new Input(models(d),peaks,ref,m,hits,text(record,"profile"));}
    private List<SignacPfmIO.Model> models(Map<String,Object> data)throws Exception{return SignacPfmIO.read(writeModels(data),SignacPfmIO.Limits.defaults(),()->false);}
    private Path writeModels(Map<String,Object> data)throws IOException{Path file=folder().resolve("models.tsv");StringBuilder text=new StringBuilder(SignacPfmIO.HEADER+"\n");for(Object raw:list(data.get("pfms"))){var model=object(raw);var rows=list(model.get("rows"));for(int i=0;i<rows.size();i++){text.append(model.get("id")).append('\t').append(model.get("name")).append('\t').append(i+1);for(Object value:list(rows.get(i)))text.append('\t').append(value);for(Object value:list(model.get("background")))text.append('\t').append(value);text.append('\n');}}Files.writeString(file,text,StandardCharsets.UTF_8);return file;}
    private Map<String,Object> dataset(Map<String,Object> record){var c=list(cases.get("cases")).stream().map(SignacScanAuditTest::object).filter(v->v.get("id").equals(record.get("id"))).findFirst().orElseThrow();return object(object(cases.get("datasets")).get(c.get("dataset")));}
    private List<Map<String,Object>> successes(){return list(original.get("results")).stream().map(SignacScanAuditTest::object).filter(v->!result(v).containsKey("error")).toList();}
    private static Map<String,Object> result(Map<String,Object> r){return object(object(r.get("result")).get("value"));}
    private Path folder()throws IOException{return Files.createDirectory(root.resolve("case-"+files.incrementAndGet()));}
    private static Map<String,Object> object(Object v){Map<String,Object> result=new LinkedHashMap<>();for(var e:((Map<?,?>)v).entrySet())result.put((String)e.getKey(),e.getValue());return result;}
    private static List<?> list(Object v){return (List<?>)v;}
    private static List<?> array(Object v){return v==null?List.of():v instanceof List<?> values?values:List.of(v);}
    private static List<String> strings(Object v){return array(v).stream().map(String.class::cast).toList();}
    private static String text(Map<String,Object> v,String key){return (String)v.get(key);}
    private static int integer(Map<String,Object> v,String key){return ((Number)v.get(key)).intValue();}
}
